import users from "../../constants/data";

import "./DataGeneration.css";

const DataGeneration = () => {
    console.log ()
  return (
    <div>
      {users.map((elm, index) => {
        <div key={index}>
          <h2>{elm.name}</h2>
          <h3>{elm.username}</h3>
          <p>{elm.email}</p>
          <p>{elm.phone}</p>
          <p>{elm.website}</p>
        </div>;
      })}
    </div>
  );
};

export default DataGeneration;
